static uint32_t oled_timer = 0;
static uint8_t  oled_frame = 0;

bool oled_task_user(void) {
    if (!startup_finished) {
        if (timer_elapsed32(oled_timer) > 43) {
            oled_timer = timer_read32();
            oled_clear();
            switch (oled_frame) {
                case 0:
                    oled_write_raw_P(startup0, sizeof(startup0));
                    break;

                case 1:
                    oled_write_raw_P(startup1, sizeof(startup0));
                    break;

                case 2:
                    oled_write_raw_P(startup2, sizeof(startup2));
                    break;

                case 3:
                    oled_write_raw_P(startup3, sizeof(startup3));
                    break;

                case 4:
                    oled_write_raw_P(startup4, sizeof(startup4));
                    break;

                case 5:
                    oled_write_raw_P(startup5, sizeof(startup5));
                    break;

                case 6:
                    oled_write_raw_P(startup6, sizeof(startup6));
                    break;

                case 7:
                    oled_write_raw_P(startup7, sizeof(startup7));
                    break;

                case 8:
                    oled_write_raw_P(startup8, sizeof(startup8));
                    break;

                case 9:
                    oled_write_raw_P(startup9, sizeof(startup9));
                    break;

                case 10:
                    oled_write_raw_P(startup10, sizeof(startup10));
                    break;

                case 11:
                    oled_write_raw_P(startup11, sizeof(startup11));
                    break;

                case 12:
                    oled_write_raw_P(startup12, sizeof(startup12));
                    break;

                case 13:
                    oled_write_raw_P(startup13, sizeof(startup13));
                    break;

                case 14:
                    oled_write_raw_P(startup14, sizeof(startup14));
                    break;

                case 15:
                    oled_write_raw_P(startup15, sizeof(startup15));
                    break;

                case 16:
                    oled_write_raw_P(startup16, sizeof(startup16));
                    break;

                case 17:
                    oled_write_raw_P(startup17, sizeof(startup17));
                    break;

                case 18:
                    oled_write_raw_P(startup18, sizeof(startup18));
                    break;

                case 19:
                    oled_write_raw_P(startup19, sizeof(startup19));
                    break;

                case 20:
                    oled_write_raw_P(startup20, sizeof(startup20));
                    break;

                case 21:
                    oled_write_raw_P(startup21, sizeof(startup21));
                    break;

                case 22:
                    oled_write_raw_P(startup22, sizeof(startup22));
                    startup_finished = true;
                    break;
            }

            oled_frame++;

            if (oled_frame > 22) oled_frame = 22;
        }

        return false;
    } else {
        render_anim(); // renders pixelart

        oled_set_cursor(0, 0);                           // sets cursor to (row, column) using charactar spacing (5 rows on 128x32 screen, anything more will overflow back to the top)
        sprintf(wpm_str, "WPM:%03d", get_current_wpm()); // edit the string to change wwhat shows up, edit %03d to change how many digits show up
        oled_write(wpm_str, false);                      // writes wpm on top left corner of string

        led_t led_state = host_keyboard_led_state(); // caps lock stuff, prints CAPS on new line if caps led is on
        oled_set_cursor(0, 1);
        oled_write_P(led_state.caps_lock ? PSTR("CAPS") : PSTR("       "), false);
    }

    return false;
}